// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics.FilterPassEstimate;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PatternKey;
import org.eclipse.rdf4j.sail.lmdb.sketch.SketchSnapshotIdentity;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The heuristic filter-pass cache answers without making the reads of its computation: the computation's slice of the
 * planning log is kept with the entry (charged to it) and spliced into the log of every planning that is served the
 * estimate, whether by a hit or by waiting for the owner's flight, and also when the computation ran outside a planning
 * scope.
 */
class LmdbPlanningReadLogSpliceTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final PatternKey PATTERN = new PatternKey(VF.createIRI("urn:read-log-splice:p"), 1);

	@Test
	void aHitSplicesTheReadsOfTheComputationEvenWhenItRanOutsideAPlanning(@TempDir Path directory) {
		LmdbFilterSelectivityStats filters = filters(directory);
		LmdbHeuristicFilterPassCache cache = new LmdbHeuristicFilterPassCache(8, 1, 1024 * 1024L);
		LmdbHeuristicFilterPassCache.Revision revision = revision();

		// Computed outside any planning scope: a private scope still records the computation's reads.
		cache.getOrCompute(filter(), revision, () -> revision, () -> computation(filters));
		LmdbPlanningReadLog.Log served = record(
				() -> cache.getOrCompute(filter(), revision, () -> revision, () -> computation(filters)));
		LmdbPlanningReadLog.Log made = record(() -> computation(filters));

		assertAll(
				() -> assertEquals(1L, cache.hits(), "COVERAGE_PREREQUISITE: the second request hit the cache"),
				() -> assertTrue(served.complete(), served.incompleteReason()),
				() -> assertEquals(made.reads(), served.reads(), "the hit replays the reads of the computation"));
	}

	@Test
	void anEntryIsChargedTheBytesOfItsSlice(@TempDir Path directory) {
		LmdbFilterSelectivityStats filters = filters(directory);
		LmdbHeuristicFilterPassCache withReads = new LmdbHeuristicFilterPassCache(8, 1, 1024 * 1024L);
		LmdbHeuristicFilterPassCache withoutReads = new LmdbHeuristicFilterPassCache(8, 1, 1024 * 1024L);
		LmdbHeuristicFilterPassCache.Revision revision = revision();

		withReads.getOrCompute(filter(), revision, () -> revision, () -> computation(filters));
		withoutReads.getOrCompute(filter(), revision, () -> revision, () -> heuristic(0.25d));
		LmdbPlanningReadLog.Log slice = record(() -> computation(filters));
		LmdbPlanningReadLog.Log empty = record(() -> {
		});

		assertEquals(slice.retainedBytes() - empty.retainedBytes(),
				withReads.retainedBytes() - withoutReads.retainedBytes(),
				"each entry is charged exactly the bytes of the slice it retains");
	}

	@Test
	void aWaiterSplicesTheReadsOfTheOwnersComputation(@TempDir Path directory) throws Exception {
		LmdbFilterSelectivityStats filters = filters(directory);
		LmdbHeuristicFilterPassCache cache = new LmdbHeuristicFilterPassCache(8, 1, 1024 * 1024L);
		LmdbHeuristicFilterPassCache.Revision revision = revision();
		CountDownLatch computing = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		ExecutorService owner = Executors.newSingleThreadExecutor();
		try {
			Future<FilterPassEstimate> owned = owner.submit(() -> cache.getOrCompute(filter(), revision,
					() -> revision, () -> {
						computing.countDown();
						await(release);
						return computation(filters);
					}));
			await(computing);
			List<LmdbPlanningReadLog.Log> waiterLogs = new ArrayList<>();
			Thread waiter = new Thread(() -> waiterLogs.add(record(() -> cache.getOrCompute(filter(), revision,
					() -> revision, () -> heuristic(0.5d)))));
			waiter.start();
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10L);
			while (waiter.getState() != Thread.State.WAITING && waiter.getState() != Thread.State.TIMED_WAITING
					&& System.nanoTime() < deadline) {
				Thread.onSpinWait();
			}
			assertTrue(waiter.getState() == Thread.State.WAITING || waiter.getState() == Thread.State.TIMED_WAITING,
					"COVERAGE_PREREQUISITE: the waiter waits on the owner's flight");
			release.countDown();
			owned.get(10L, TimeUnit.SECONDS);
			waiter.join(10_000L);
			LmdbPlanningReadLog.Log made = record(() -> computation(filters));

			assertAll(
					() -> assertEquals(1, waiterLogs.size()),
					() -> assertTrue(waiterLogs.get(0).complete(), waiterLogs.get(0).incompleteReason()),
					() -> assertEquals(made.reads(), waiterLogs.get(0).reads(),
							"the waiter's planning replays the reads of the owner's computation"));
		} finally {
			release.countDown();
			owner.shutdownNow();
		}
	}

	private static FilterPassEstimate computation(LmdbFilterSelectivityStats filters) {
		filters.getFilterPassRatio(PATTERN, "computed");
		filters.getPatternObservationCount(PATTERN);
		return heuristic(0.25d);
	}

	private static LmdbPlanningReadLog.Log record(Runnable reads) {
		List<LmdbPlanningReadLog.Log> logs = new ArrayList<>();
		Thread owner = Thread.currentThread();
		Consumer<LmdbPlanningReadLog.Log> previous = LmdbPlanningReadLog.setCompletedPlanningObserver(log -> {
			if (Thread.currentThread() == owner) {
				logs.add(log);
			}
		});
		try {
			LmdbPlanningReadLog.beginPlanning();
			try {
				reads.run();
			} finally {
				LmdbPlanningReadLog.endPlanning();
			}
		} finally {
			// The observer is process-wide; each recording restores the one it replaced.
			LmdbPlanningReadLog.setCompletedPlanningObserver(previous);
		}
		return logs.get(0);
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(10L, TimeUnit.SECONDS)) {
				throw new AssertionError("test latch was not released");
			}
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted", interrupted);
		}
	}

	private static Filter filter() {
		StatementPattern pattern = new StatementPattern(Var.of("subject"),
				Var.of("predicate", VF.createIRI("urn:read-log-splice:filter")), Var.of("object"));
		return new Filter(pattern, new ValueConstant(VF.createLiteral(true)));
	}

	private static FilterPassEstimate heuristic(double ratio) {
		return new FilterPassEstimate(ratio, FilterPassEstimate.Source.HEURISTIC);
	}

	private static LmdbHeuristicFilterPassCache.Revision revision() {
		return new LmdbHeuristicFilterPassCache.Revision(17L, 2L, 3L, 4L, true);
	}

	private static LmdbFilterSelectivityStats filters(Path directory) {
		return new LmdbFilterSelectivityStats(directory.resolve("read-log-splice.rjes"), mock(TripleStore.class),
				mock(ValueStore.class), false, 0L, 0, false, () -> new SketchSnapshotIdentity(1L, 2L, 3L), 0,
				() -> true, () -> 0L);
	}
}
